using System;using System.IO;using System.Reflection;using System.Reflection.Emit;using System.Runtime.Serialization;using System.Collections.Generic;using System.Linq;using ElementalHearts;using Verse;using Verse.AI;using UnityEngine;
class TempestDragonRegression {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static T Empty<T>(){return (T)FormatterServices.GetUninitializedObject(typeof(T));}
 static void Set(object o,string key,object value){o.GetType().GetField(key,F).SetValue(o,value);}
 static object Get(object o,string key){return o.GetType().GetField(key,F).GetValue(o);}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(TempestDragonRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static List<MethodBase> Calls(MethodInfo method){var opcodes=typeof(OpCodes).GetFields(BindingFlags.Static|BindingFlags.Public).Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)).ToDictionary(o=>(ushort)o.Value);var il=method.GetMethodBody().GetILAsByteArray();var found=new List<MethodBase>();for(int i=0;i<il.Length;){ushort code=il[i++];if(code==254)code=(ushort)(0xfe00|il[i++]);var op=opcodes[code];switch(op.OperandType){case OperandType.InlineMethod:found.Add(method.Module.ResolveMethod(BitConverter.ToInt32(il,i)));i+=4;break;case OperandType.InlineSwitch:int count=BitConverter.ToInt32(il,i);i+=4+4*count;break;case OperandType.InlineNone:break;case OperandType.ShortInlineBrTarget:case OperandType.ShortInlineI:case OperandType.ShortInlineVar:i++;break;case OperandType.InlineVar:i+=2;break;case OperandType.InlineI8:case OperandType.InlineR:i+=8;break;default:i+=4;break;}}return found;}
 static void Run(){
  var origin=new IntVec3(10,0,10);var target=new IntVec3(16,0,10);IntVec3 turn,end;
  Func<IntVec3,bool> free=c=>c.x>=0&&c.z>=0&&c.x<=30&&c.z<=30&&c!=target;
  Check(TempestDragonRules.Route(origin,target,10,0,free,(a,b)=>true,out turn,out end),"Open two-leg route rejected");Check(turn.z>origin.z&&end.x>target.x&&end.DistanceToSquared(target)<=2,"First approach lacks preferred side bend and through-target landing");var d1=turn-origin;var d2=end-turn;Check(d1.x*d2.z-d1.z*d2.x!=0,"Route collapses to a straight approach without a bend");
  Check(TempestDragonRules.Route(origin,target,10,1,free,(a,b)=>true,out turn,out end)&&turn.z<origin.z,"Successive approaches do not alternate preferred bend side");
  Check(!TempestDragonRules.Route(origin,target,1,0,free,(a,b)=>true,out turn,out end),"Range limit ignored");Check(!TempestDragonRules.Route(origin,target,10,0,c=>false,(a,b)=>true,out turn,out end),"Occupied stopping points accepted");Check(!TempestDragonRules.Route(origin,target,10,0,free,(a,b)=>false,out turn,out end),"Blocked legs accepted");
  var wall=new IntVec3(13,0,11);Func<IntVec3,IntVec3,bool> path=(a,b)=>!LightningGeometry.Trace(a,b).Contains(wall);Check(TempestDragonRules.Route(origin,target,10,0,c=>free(c)&&c!=wall,path,out turn,out end)&&path(origin,turn)&&path(turn,end),"Chosen route crosses a blocked supercover cell");
  foreach(int n in new[]{0,1,4,5,6})foreach(bool eligible in new[]{false,true})foreach(bool seen in new[]{false,true})Check(TempestDragonRules.CanVisit(n,eligible,seen)==(n<5&&eligible&&!seen),"Distinct-target/cap policy");foreach(float length in new[]{0,1,5,10,100})Check(TempestDragonRules.Duration(length)>=4&&TempestDragonRules.Duration(length)<=10,"Unbounded segment duration");for(int age=0;age<24;age++)Check(TempestDragonRules.Frame(age)==age/3,"Sequence timing");Check(TempestDragonRules.Frame(-10)==0&&TempestDragonRules.Frame(100)==7,"Frame bounds");
  Console.WriteLine("PASS: alternating two-line zigzag routes, through-target landings, occupancy/range/wall rejection, five distinct visits, bounded timing and eight-frame cadence.");
  var pawn=Empty<Pawn>();pawn.jobs=Empty<Pawn_JobTracker>();var job=new Job{def=new JobDef{defName=TempestDragon.JobName}};job.targetB=new IntVec3(14,0,12);job.targetC=new IntVec3(17,0,10);pawn.jobs.curJob=job;
  var driver=new JobDriver_TempestDragon{pawn=pawn,job=job};Set(pawn.jobs,"curDriver",driver);Set(driver,"start",origin);Set(driver,"duration",8);Set(driver,"elapsed",4);Set(driver,"leg",0);Set(driver,"initialized",true);Set(driver,"moving",true);
  Check(driver.VisualAt(0).x==10.5f&&driver.VisualAt(4).x==12.5f&&driver.VisualAt(4).z==11.5f&&driver.VisualAt(8).x==14.5f,"First segment not linear");Set(driver,"start",job.targetB.Cell);Set(driver,"leg",1);Check(driver.VisualAt(0).x==14.5f&&driver.VisualAt(8).x==17.5f&&driver.VisualAt(8).z==10.5f,"Second segment endpoints wrong");
  Check(TempestDragon.Busy(pawn)&&ElementalAnimationBridge.Controlled(pawn),"Chain does not lock concurrent skills");var toils=new List<Toil>((IEnumerable<Toil>)typeof(JobDriver_TempestDragon).GetMethod("MakeNewToils",F).Invoke(driver,null));Check(toils.Count==2&&toils[0].defaultCompleteMode==ToilCompleteMode.Never&&toils[0].handlingFacing&&toils[1].defaultDuration==6,"Native chain job/recovery structure");job.def.defName="Wait_Combat";Check(!TempestDragon.Busy(pawn)&&!ElementalAnimationBridge.Controlled(pawn),"Replacement job retains chain skill gate");
  var calls=Calls(typeof(JobDriver_TempestDragon).GetMethod("Hit",F));int commitment=calls.FindIndex(m=>m.DeclaringType==typeof(HashSet<int>)&&m.Name=="Add"),damage=calls.FindIndex(m=>m.DeclaringType==typeof(LightningCombat)&&m.Name=="Strike");Check(commitment>=0&&damage>commitment,"Impact commitment is not recorded before damage");Check(Calls(typeof(HediffComp_TempestCircuit).GetMethod("TryCast")).Any(m=>m.DeclaringType==typeof(TempestDragon)&&m.Name=="TryStart"),"Fifth slot does not launch chain");
  Console.WriteLine("PASS: continuous linear draw positions, native held job, hit commitment ordering, fifth-slot dispatch and immediate gate release on replacement order.");
  var fx=new MapComponent_TempestDragonVfx(null);int token=-1;for(int i=0;i<10000;i++)token=fx.Begin(Vector3.zero,Vector3.one,i);Check(((Array)Get(fx,"trails")).Length==128&&!fx.Extend(0,Vector3.zero)&&fx.Extend(token,Vector3.one),"Trail pool grows or stale handles overwrite new trails");
  var map=new MapComponent_Thunderstorm(null);var zones=(List<ThunderstormZone>)Get(map,"zones");zones.Add(new ThunderstormZone{circuit=true});zones.Add(new ThunderstormZone{circuit=false});map.DiscardLegacyZones();Check(zones.Count==0&&!map.Queue(null,IntVec3.Invalid,true)&&!map.Queue(null,IntVec3.Invalid,false),"Legacy pulse zones remain active");
  Set(driver,"visited",new HashSet<int>{101,102,103});Set(driver,"struck",new HashSet<int>{101,102});var payload=new TempestDragonSaveCase{driver=driver,job=job};string file=Path.Combine(Path.GetTempPath(),"TempestDragon_"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"DragonTest");Scribe_Deep.Look(ref payload,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);Check(xml.SelectSingleNode("DragonTest/state/driver/EH_dragonElapsed").InnerText=="4"&&xml.SelectSingleNode("DragonTest/state/driver/EH_dragonLeg").InnerText=="1"&&xml.SelectNodes("DragonTest/state/driver/EH_dragonVisited/li").Count==3&&xml.SelectNodes("DragonTest/state/driver/EH_dragonStruck/li").Count==2,"Native save loses segment progress or unique IDs");Check(xml.SelectSingleNode("DragonTest/state/job/targetB").InnerText.Contains("14")&&xml.SelectSingleNode("DragonTest/state/job/targetC").InnerText.Contains("17"),"Native job save loses zigzag endpoints");File.Delete(file);
  Console.WriteLine("PASS: 10,000 trail insertions stay within 128 slots with stale-handle protection, retired zone cleanup, and native save output for route/progress/visited/struck IDs.");Console.WriteLine("LIMIT: native loading, live combat, GPU rendering and frame-time profiling are not covered.");
 }
}
public class TempestDragonSaveCase:IExposable {public JobDriver_TempestDragon driver;public Job job;public void ExposeData(){Scribe_Deep.Look(ref driver,"driver");Scribe_Deep.Look(ref job,"job");}}
